const deleteRelationInUi = async (page, name) => {
  await expect(async () => {
    const mutation = page.waitForResponse((r) => r.request().method() === 'DELETE' && r.url().includes('/relationTypes'));
    await page.getByTestId(`delete-${name}`).click();
    await page.getByTestId('confirm-delete').click();
    expect((await mutation).status()).toBeLessThan(300);
  }).toPass();
};
// caller:
expect(await page.getByTestId(`relation-name-${name}`).count()).toBe(0);
